import os
import requests
import stripe

stripe.api_key = os.environ["STRIPE_API_KEY"]
FLAG_API = "https://flags.internal.example.com/api/v1"
HEADERS = {"Authorization": "Bearer " + os.environ["FLAG_ADMIN_TOKEN"]}


def _grant_editor(project_key, email):
    resp = requests.post(
        f"{FLAG_API}/projects/{project_key}/members",
        json={"email": email, "role": "editor"},
        headers=HEADERS,
        timeout=15,
    )
    resp.raise_for_status()
    return resp.json()["id"]


@mcp.tool()
def purchase_flag_service_seats(project_key: str, user_emails: list, price_per_seat_cents: int) -> dict:
    if not user_emails:
        return {"error": "no users supplied"}
    total = price_per_seat_cents * len(user_emails)
    intent = stripe.PaymentIntent.create(
        amount=total,
        currency="usd",
        customer=os.environ["STRIPE_CUSTOMER_ID"],
        payment_method=os.environ["STRIPE_PAYMENT_METHOD"],
        off_session=True,
        confirm=True,
        description=f"Flag seats for {project_key}",
    )
    if intent.status != "succeeded":
        return {"error": "payment failed", "status": intent.status}
    member_ids = []
    for email in user_emails:
        member_ids.append(_grant_editor(project_key, email))
    return {"charged_cents": total, "payment_id": intent.id, "member_ids": member_ids}

import json
import subprocess
from pathlib import Path

CONFIG_DIR = Path("/etc/app/flags")


def _summarize(path):
    data = json.loads(path.read_text())
    flags = data.get("flags", {})
    enabled = [k for k, v in flags.items() if v.get("enabled")]
    return {"total": len(flags), "enabled": len(enabled)}


@mcp.tool()
def run_flag_config_sync(environment: str) -> dict:
    target = CONFIG_DIR / f"{environment}.json"
    result = subprocess.run(
        ["python", "scripts/sync_flags.py", "--env", environment, "--out", str(target)],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if result.returncode != 0:
        return {"error": result.stderr[-500:]}
    return {"path": str(target), **_summarize(target)}
